/**
 * Parhelion — the standing stones as Blender wrote them (parhelion-menhir-models.js, generated by
 * scripts/blender/parhelion_menhirs.py): that the module holds the three stones as plain numbers
 * in the ranges it names, that each is one unit tall on its foot and within its budget, that its
 * skin is one sheet wound outward with normals that agree with it, and that the three are three
 * shapes (a slab, a point, a notched slab) from the front and from the side.
 */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import {
    PARHELION_MENHIRS as MENHIRS, PARHELION_MENHIR_NAMES as NAMES,
} from '../../src/themes/parhelion/parhelion-menhir-models.js';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
/** Triangles and (split) vertices a stone may cost: it is drawn dozens of times, a few pixels wide. */
const TRIANGLES = [350, 700];
const VERTICES = 900;
/**
 * What each stone was asked to be, in unit heights: how wide (x) and how thick (z) at its foot,
 * each within a fifth or so.
 */
const FOOT = {
    tall: { width: [0.21, 0.31], thickness: [0.1, 0.16] },
    tooth: { width: [0.29, 0.39], thickness: [0.16, 0.24] },
    broad: { width: [0.43, 0.57], thickness: [0.13, 0.2] },
};

const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

/** A stone as the theme will read it: positions in unit heights, unit normals, 0..1 occlusion. */
function read(model) {
    const count = model.ao.length;
    const at = (v) => [0, 1, 2].map((k) => model.positions[v * 3 + k] * model.quant);
    const normal = (v) => [0, 1, 2].map((k) => model.normals[v * 3 + k] / 127);
    const triangles = [];
    for (let t = 0; t < model.index.length; t += 3) triangles.push(model.index.slice(t, t + 3));
    const lo = [Infinity, Infinity, Infinity];
    const hi = [-Infinity, -Infinity, -Infinity];
    for (let v = 0; v < count; v++) {
        at(v).forEach((c, k) => {
            lo[k] = Math.min(lo[k], c);
            hi[k] = Math.max(hi[k], c);
        });
    }
    return {
        count, at, normal, triangles, lo, hi,
    };
}

/**
 * Where the plane at height `y` cuts the stone, along `axis` (0: x, the front view's width; 2: z,
 * the side view's): the spans it covers, merged (two spans: two horns with sky between them).
 */
function spans(mesh, y, axis) {
    const pieces = [];
    for (const tri of mesh.triangles) {
        const p = tri.map(mesh.at);
        const cut = [];
        for (let i = 0; i < 3; i++) {
            const u = p[i];
            const v = p[(i + 1) % 3];
            if ((u[1] > y) !== (v[1] > y)) cut.push(u[axis] + (v[axis] - u[axis]) * ((y - u[1]) / (v[1] - u[1])));
        }
        if (cut.length === 2) pieces.push([Math.min(...cut), Math.max(...cut)]);
    }
    pieces.sort((a, b) => a[0] - b[0]);
    const merged = [];
    for (const piece of pieces) {
        const last = merged[merged.length - 1];
        if (last && piece[0] <= last[1] + 1e-9) last[1] = Math.max(last[1], piece[1]);
        else merged.push([...piece]);
    }
    return merged;
}

/** The stone's whole extent along `axis` at height `y` (0 where the plane misses it). */
function extent(mesh, y, axis) {
    const found = spans(mesh, y, axis);
    return found.length ? found[found.length - 1][1] - found[0][0] : 0;
}

/** The middle of the stone's section at height `y`: its own axis there (a stone may lean). */
function middle(mesh, y) {
    return [0, 2].map((axis) => {
        const found = spans(mesh, y, axis);
        return (found[0][0] + found[found.length - 1][1]) / 2;
    });
}

/** Widths (or thicknesses) at nineteen heights, foot to top: the silhouette as numbers. */
const HEIGHTS = Array.from({ length: 19 }, (_, i) => 0.05 + i * 0.05);
const profile = (mesh, axis) => HEIGHTS.map((y) => extent(mesh, y, axis));
const apart = (a, b) => a.reduce((sum, v, i) => sum + Math.abs(v - b[i]), 0) / a.length;

const ALL = NAMES.map((name) => [name, MENHIRS[name]]);

describe('parhelion menhir models', () => {
    it('holds three stones: tall, tooth, broad', () => {
        expect(NAMES).toEqual(['tall', 'tooth', 'broad']);
        expect(Object.keys(MENHIRS)).toEqual(['tall', 'tooth', 'broad']);
        expect(Object.isFrozen(MENHIRS)).toBe(true);
    });

    it.each(ALL)('%s is plain numbers in the ranges it names, with lengths that agree', (_name, model) => {
        const count = model.ao.length;
        expect(model.quant).toBeGreaterThan(0);
        expect(model.vertexCount).toBe(count);
        expect(model.triangleCount).toBe(model.index.length / 3);
        expect(model.positions).toHaveLength(count * 3);
        expect(model.normals).toHaveLength(count * 3);
        expect(model.index.length % 3).toBe(0);
        const whole = (values, lo, hi) => values.every((v) => Number.isInteger(v) && v >= lo && v <= hi);
        expect(whole(model.positions, -32768, 32767)).toBe(true);
        expect(whole(model.normals, -127, 127)).toBe(true);
        expect(whole(model.ao, 0, 255)).toBe(true);
        expect(whole(model.index, 0, Math.min(count - 1, 65535))).toBe(true);
        // Every vertex is used: a spare one is dead weight in every stone of both rows.
        expect(new Set(model.index).size).toBe(count);
    });

    it.each(ALL)('%s is within its budget', (_name, model) => {
        expect(model.triangleCount).toBeGreaterThanOrEqual(TRIANGLES[0]);
        expect(model.triangleCount).toBeLessThanOrEqual(TRIANGLES[1]);
        expect(model.vertexCount).toBeLessThanOrEqual(VERTICES);
    });

    it.each(ALL)('%s is one unit tall, its foot under the ground line and on the axis', (name, model) => {
        const mesh = read(model);
        // The highest vertex at one; the ground line at nought; the mesh a little way under it.
        expect(Math.abs(mesh.hi[1] - 1)).toBeLessThan(1e-3);
        expect(mesh.lo[1]).toBeLessThan(0);
        expect(mesh.lo[1]).toBeGreaterThan(-0.15);
        expect(Math.abs(mesh.lo[1] + model.bury)).toBeLessThan(1e-3);
        // (What the module says of its own extents is true.)
        mesh.lo.forEach((v, k) => expect(Math.abs(v - model.min[k])).toBeLessThan(1e-3));
        mesh.hi.forEach((v, k) => expect(Math.abs(v - model.max[k])).toBeLessThan(1e-3));
        // Its section at the ground straddles the origin evenly, and so (more loosely: they are
        // not spread evenly) do the vertices down there.
        const [mx, mz] = middle(mesh, 0);
        expect(Math.abs(mx)).toBeLessThan(0.02);
        expect(Math.abs(mz)).toBeLessThan(0.02);
        const low = [];
        for (let v = 0; v < mesh.count; v++) if (mesh.at(v)[1] < 0.02) low.push(mesh.at(v));
        expect(low.length).toBeGreaterThanOrEqual(6);
        expect(Math.abs(low.reduce((sum, p) => sum + p[0], 0) / low.length)).toBeLessThan(0.06);
        expect(Math.abs(low.reduce((sum, p) => sum + p[2], 0) / low.length)).toBeLessThan(0.03);
        // The proportions it was asked for, and its broad axis is x: turned, it shows a narrow edge.
        const width = extent(mesh, 0.05, 0);
        const thickness = extent(mesh, 0.05, 2);
        expect(width).toBeGreaterThan(FOOT[name].width[0]);
        expect(width).toBeLessThan(FOOT[name].width[1]);
        expect(thickness).toBeGreaterThan(FOOT[name].thickness[0]);
        expect(thickness).toBeLessThan(FOOT[name].thickness[1]);
        expect(mesh.hi[2] - mesh.lo[2]).toBeLessThan(0.65 * (mesh.hi[0] - mesh.lo[0]));
        // It stands on the whole of its foot: nothing is wider than it by much higher up.
        expect(mesh.hi[0] - mesh.lo[0]).toBeLessThan(width + 0.05);
    });

    it.each(ALL)('%s is one sheet, open only underneath, with no sliver in it', (_name, model) => {
        const mesh = read(model);
        // Vertices are split along the arrises: the skin is what they make welded by place.
        const place = (v) => model.positions.slice(v * 3, v * 3 + 3).join(',');
        const edges = new Map();
        let slivers = 0;
        for (const tri of mesh.triangles) {
            const p = tri.map(mesh.at);
            const lengths = [0, 1, 2].map((i) => Math.hypot(...sub(p[(i + 1) % 3], p[i])));
            const twice = Math.hypot(...cross(sub(p[1], p[0]), sub(p[2], p[0])));
            // (Its height over its longest edge: three corners along one arris have none.)
            if (twice / Math.max(...lengths) < 1e-3) slivers += 1;
            for (let i = 0; i < 3; i++) {
                const key = `${place(tri[i])}>${place(tri[(i + 1) % 3])}`;
                edges.set(key, (edges.get(key) ?? 0) + 1);
            }
        }
        expect(slivers).toBe(0);
        let open = 0;
        for (const [key, uses] of edges) {
            // Every edge runs once each way, but for the rim of the foot (at the lowest height).
            expect(uses).toBe(1);
            const [from, to] = key.split('>');
            if (!edges.has(`${to}>${from}`)) {
                open += 1;
                expect(Number(from.split(',')[1])).toBe(Math.round(mesh.lo[1] / model.quant));
                expect(Number(to.split(',')[1])).toBe(Math.round(mesh.lo[1] / model.quant));
            }
        }
        expect(open).toBeGreaterThanOrEqual(3);
        expect(open).toBeLessThan(40);
    });

    it.each(ALL)('%s is wound outward, with unit normals that agree with its faces', (_name, model) => {
        const mesh = read(model);
        // Unit normals, to what eight bits a component can say.
        for (let v = 0; v < mesh.count; v++) {
            const length = Math.hypot(...mesh.normal(v));
            expect(length).toBeGreaterThan(0.985);
            expect(length).toBeLessThan(1.015);
        }
        let agree = 0;
        let outward = 0;
        let volume = 0;
        const inside = [0, 0.4, 0];
        for (const tri of mesh.triangles) {
            const [a, b, c] = tri.map(mesh.at);
            const face = cross(sub(b, a), sub(c, a));
            const size = Math.hypot(...face);
            // The face looks the way its corners' normals do ...
            const summed = tri.map(mesh.normal).reduce((sum, n) => sum.map((v, k) => v + n[k]), [0, 0, 0]);
            if (dot(face, summed) > 0) agree += 1;
            // ... and away from the stone's own axis at its height (a level face: up, to the sky).
            const centre = [0, 1, 2].map((k) => (a[k] + b[k] + c[k]) / 3);
            const [ax, az] = middle(mesh, Math.min(0.99, Math.max(mesh.lo[1] + 0.01, centre[1])));
            const unit = face.map((v) => v / size);
            const steep = Math.hypot(unit[0], unit[2]) > 0.35;
            if (steep ? unit[0] * (centre[0] - ax) + unit[2] * (centre[2] - az) > 0 : unit[1] > 0) outward += 1;
            volume += dot(sub(a, inside), cross(sub(b, inside), sub(c, inside))) / 6;
        }
        const total = mesh.triangles.length;
        expect(agree).toBe(total);
        // (The walls of a notch and of a spall's ledge look toward the axis: a few of them.)
        expect(outward / total).toBeGreaterThanOrEqual(0.9);
        // Counter-clockwise seen from outside: the volume it encloses is positive, and a slab's.
        expect(volume).toBeGreaterThan(0.015);
        expect(volume).toBeLessThan(0.08);
    });

    it.each(ALL)('%s is open to the sky but for its cracks and ledges', (_name, model) => {
        const ao = model.ao.map((v) => v / 255);
        expect(Math.max(...ao)).toBe(1);
        expect(ao.reduce((sum, v) => sum + v, 0) / ao.length).toBeGreaterThan(0.75);
        // Darker somewhere: over a ledge, in the notch, where a block stands against another.
        expect(Math.min(...ao)).toBeLessThan(0.6);
        const dark = ao.filter((v) => v < 0.78).length / ao.length;
        expect(dark).toBeGreaterThan(0.03);
        expect(dark).toBeLessThan(0.4);
    });

    it('is three silhouettes, from the front and turned', () => {
        const meshes = Object.fromEntries(ALL.map(([name, model]) => [name, read(model)]));
        const front = Object.fromEntries(NAMES.map((name) => [name, profile(meshes[name], 0)]));
        const side = Object.fromEntries(NAMES.map((name) => [name, profile(meshes[name], 2)]));
        // No two have the same width up their height (the mean gap, in unit heights: at thirty
        // pixels a gap of 0.03 is a pixel all the way up), nor the same thickness seen edge-on.
        for (const [a, b] of [['tall', 'tooth'], ['tall', 'broad'], ['tooth', 'broad']]) {
            expect(apart(front[a], front[b])).toBeGreaterThan(0.03);
            expect(apart(side[a], side[b])).toBeGreaterThan(0.015);
        }
        const at = (values, y) => values[HEIGHTS.findIndex((h) => Math.abs(h - y) < 1e-9)];
        // The tall slab keeps its width nearly to its shoulder; the tooth tapers to a point from
        // a wide foot (in thickness too); the broad slab is twice the tall one's width.
        expect(at(front.tall, 0.75) / at(front.tall, 0.05)).toBeGreaterThan(0.7);
        expect(at(front.tooth, 0.95) / at(front.tooth, 0.05)).toBeLessThan(0.3);
        expect(at(side.tooth, 0.95) / at(side.tooth, 0.05)).toBeLessThan(0.55);
        expect(at(front.broad, 0.5) / at(front.tall, 0.5)).toBeGreaterThan(1.5);
        // The tall slab's top slants: at nine tenths of its height there is half of it left.
        expect(at(front.tall, 0.9) / at(front.tall, 0.5)).toBeLessThan(0.65);
        // The broad slab's top is notched: under its low horn's top the sky shows between two
        // horns (the other two are one piece at every height).
        expect(spans(meshes.broad, 0.84, 0)).toHaveLength(2);
        const [high, low] = spans(meshes.broad, 0.84, 0);
        expect(low[0] - high[1]).toBeGreaterThan(0.03);
        expect(spans(meshes.broad, 0.95, 0)).toHaveLength(1);
        for (const name of ['tall', 'tooth']) {
            for (const y of HEIGHTS) expect(spans(meshes[name], y, 0)).toHaveLength(1);
        }
        // Its bed stands proud of the slab above it: a ledge round the foot.
        expect(at(front.broad, 0.3) - at(front.broad, 0.6)).toBeGreaterThan(0.03);
        expect(at(side.broad, 0.3) - at(side.broad, 0.6)).toBeGreaterThan(0.015);
    });

    it('is a small module, generated by the Blender script', () => {
        const file = path.join(root, 'src/themes/parhelion/parhelion-menhir-models.js');
        const source = readFileSync(file, 'utf8');
        expect(source.startsWith('/* eslint-disable */')).toBe(true);
        expect(source).toMatch(/GENERATED by scripts\/blender\/parhelion_menhirs\.py/);
        expect(source.length).toBeLessThan(60 * 1024);
        // Plain data: it imports nothing.
        expect(source).not.toMatch(/\bimport\b/);
        expect(readFileSync(path.join(root, 'scripts/blender/parhelion_menhirs.py'), 'utf8'))
            .toMatch(/parhelion-menhir-models\.js/);
    });
});
